USE ccs_clearance;

CREATE TABLE IF NOT EXISTS password_reset_tokens (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 user_id INT UNSIGNED NOT NULL,
 token_hash CHAR(64) NOT NULL UNIQUE,
 expires_at DATETIME NOT NULL,
 used_at DATETIME NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
 INDEX idx_reset_user(user_id),
 INDEX idx_reset_expiry(expires_at)
) ENGINE=InnoDB;

ALTER TABLE clearances
    MODIFY status ENUM('pending','cleared','rejected') NOT NULL DEFAULT 'pending';

CREATE TABLE IF NOT EXISTS remember_tokens (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 user_id INT UNSIGNED NOT NULL,
 token_hash CHAR(64) NOT NULL UNIQUE,
 expires_at DATETIME NOT NULL,
 last_used_at DATETIME NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
 INDEX idx_remember_user(user_id),
 INDEX idx_remember_expiry(expires_at)
) ENGINE=InnoDB;
-- QA wireframe student list (safe to run on an existing database)

SELECT u.id,d.id,'pending'
FROM users u CROSS JOIN departments d
WHERE u.role='student' AND u.student_no BETWEEN '2026-0001' AND '2026-0100';
